import { Controller, Get, Post, Put, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

type Db = Parameters<Parameters<typeof transaction>[0]>[0];

const ROLE_MANAGER = '자산 담당자';
const ROLE_STAFF = '임직원';
const DATE_RE = /^\d{4}-\d{2}-\d{2}$/;
const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;

function invalid(message: string): never {
  throw new ApiError(422, 'INSPECTION_PLAN_INVALID', message);
}

function readPlan(data: Record<string, unknown>) {
  const inspectionType = typeof data.inspectionType === 'string' ? data.inspectionType.trim() : '';
  const startDate = typeof data.startDate === 'string' ? data.startDate.trim() : '';
  const endDate = typeof data.endDate === 'string' ? data.endDate.trim() : '';
  const targetScope = typeof data.targetScope === 'string' && data.targetScope.trim() !== '' ? data.targetScope : null;
  const rawManager = data.managerId;
  const managerId = (typeof rawManager === 'number' || (typeof rawManager === 'string' && rawManager.trim() !== ''))
    ? Number(rawManager)
    : NaN;
  if (inspectionType === '' || inspectionType.length > 50) {
    invalid('실사 유형을 50자 이내로 입력하세요.');
  }
  if (!DATE_RE.test(startDate) || !DATE_RE.test(endDate)) {
    invalid('실사 시작일과 종료일을 입력하세요.');
  }
  if (!Number.isInteger(managerId) || managerId <= 0) {
    invalid('실사 담당자를 선택하세요.');
  }
  // YYYY-MM-DD 형식은 글자 순서가 날짜 순서와 같다
  if (startDate > endDate) {
    invalid('실사 시작일이 종료일보다 늦을 수 없습니다.');
  }
  return { inspectionType, startDate, endDate, targetScope, managerId };
}

async function requireManager(db: Db, managerId: number) {
  const rows = await db.query(
    'SELECT employee_id FROM employee WHERE employee_id = CAST(:managerId AS bigint)',
    { managerId },
  );
  if (rows.length === 0) {
    throw new ApiError(404, 'EMPLOYEE_NOT_FOUND', '실사 담당자를 찾을 수 없습니다.');
  }
}

async function findPlan(db: Db, id: string) {
  if (!/^\d+$/.test(id)) {
    throw new ApiError(404, 'INSPECTION_PLAN_NOT_FOUND', '실사계획을 찾을 수 없습니다.');
  }
  const rows = await db.query(
    'SELECT asset_inspection_plan_id AS "assetInspectionPlanId", approval_status AS "approvalStatus" FROM asset_inspection_plan WHERE asset_inspection_plan_id = CAST(:id AS bigint)',
    { id },
  );
  if (rows.length === 0) {
    throw new ApiError(404, 'INSPECTION_PLAN_NOT_FOUND', '실사계획을 찾을 수 없습니다.');
  }
  return rows[0] as { assetInspectionPlanId: number; approvalStatus: string };
}

@Controller('api/v1')
export class FnSfr02505Controller {
  @Post('/asset-inspection-plans')
  @HttpCode(200)
  async createAssetInspectionPlan(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE_MANAGER);
    const data = checks.inputOf(req.body);
    const plan = readPlan(data);
    return transaction(async (db) => {
      await requireManager(db, plan.managerId);
      const rows = await db.query(
        'INSERT INTO asset_inspection_plan (inspection_type, start_date, end_date, target_scope, manager_id, approval_status, created_at, updated_at) '
        + 'VALUES (:inspectionType, CAST(:startDate AS date), CAST(:endDate AS date), :targetScope, CAST(:managerId AS bigint), \'신청\', now(), now()) '
        + 'RETURNING asset_inspection_plan_id AS "assetInspectionPlanId", approval_status AS "approvalStatus"',
        plan,
      );
      return rows[0];
    });
  }

  @Get('/asset-inspection-plans')
  async listAssetInspectionPlans(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE_MANAGER, ROLE_STAFF);
    const query = checks.queryOf(req.query);
    const page = query.page === undefined || query.page === '' ? 0 : Number(query.page);
    const size = query.size === undefined || query.size === '' ? DEFAULT_SIZE : Number(query.size);
    if (!Number.isInteger(page) || page < 0 || !Number.isInteger(size) || size < 1) {
      throw new ApiError(400, 'VALIDATION_FAILED', 'page와 size 값이 올바르지 않습니다.');
    }
    const limit = Math.min(size, MAX_SIZE);
    const inspectionType = typeof query.inspectionType === 'string' && query.inspectionType !== '' ? query.inspectionType : null;
    const approvalStatus = typeof query.approvalStatus === 'string' && query.approvalStatus !== '' ? query.approvalStatus : null;
    if (approvalStatus !== null && !['신청', '승인', '승인취소'].includes(approvalStatus)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '승인 상태 값이 올바르지 않습니다.');
    }
    return transaction(async (db) => {
      const where = 'WHERE (CAST(:inspectionType AS text) IS NULL OR inspection_type = :inspectionType) '
        + 'AND (CAST(:approvalStatus AS text) IS NULL OR approval_status = :approvalStatus)';
      const items = await db.query(
        'SELECT asset_inspection_plan_id AS "assetInspectionPlanId", inspection_type AS "inspectionType", '
        + 'to_char(start_date, \'YYYY-MM-DD\') AS "startDate", to_char(end_date, \'YYYY-MM-DD\') AS "endDate", '
        + 'target_scope AS "targetScope", manager_id AS "managerId", approval_status AS "approvalStatus" '
        + 'FROM asset_inspection_plan ' + where + ' ORDER BY asset_inspection_plan_id DESC '
        + 'LIMIT :limit OFFSET :offset',
        { inspectionType, approvalStatus, limit, offset: page * limit },
      );
      const counts = await db.query(
        'SELECT COUNT(*) AS "total" FROM asset_inspection_plan ' + where,
        { inspectionType, approvalStatus },
      );
      return { items, page, size: limit, total: Number((counts[0] as { total: number | string }).total) };
    });
  }

  @Put('/asset-inspection-plans/:assetInspectionPlanId')
  async updateAssetInspectionPlan(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE_MANAGER);
    const id = req.params['assetInspectionPlanId'];
    const data = checks.inputOf(req.body);
    return transaction(async (db) => {
      const current = await findPlan(db, id);
      if (current.approvalStatus === '승인') {
        throw new ApiError(409, 'INSPECTION_PLAN_APPROVED', '승인된 계획은 승인취소 후에 수정할 수 있습니다.');
      }
      const plan = readPlan(data);
      await requireManager(db, plan.managerId);
      const rows = await db.query(
        'UPDATE asset_inspection_plan SET inspection_type = :inspectionType, start_date = CAST(:startDate AS date), '
        + 'end_date = CAST(:endDate AS date), target_scope = :targetScope, manager_id = CAST(:managerId AS bigint), updated_at = now() '
        + 'WHERE asset_inspection_plan_id = CAST(:id AS bigint) '
        + 'RETURNING asset_inspection_plan_id AS "assetInspectionPlanId"',
        { ...plan, id },
      );
      return rows[0];
    });
  }

  @Post('/asset-inspection-plans/:assetInspectionPlanId/approve')
  @HttpCode(200)
  async approveAssetInspectionPlan(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE_MANAGER, ROLE_STAFF);
    const id = req.params['assetInspectionPlanId'];
    return transaction(async (db) => {
      const current = await findPlan(db, id);
      if (current.approvalStatus !== '신청') {
        throw new ApiError(409, 'INSPECTION_PLAN_STATUS_CONFLICT', '신청 상태의 계획만 승인할 수 있습니다.');
      }
      const rows = await db.query(
        'UPDATE asset_inspection_plan SET approval_status = \'승인\', updated_at = now() '
        + 'WHERE asset_inspection_plan_id = CAST(:id AS bigint) RETURNING approval_status AS "approvalStatus"',
        { id },
      );
      return rows[0];
    });
  }

  @Post('/asset-inspection-plans/:assetInspectionPlanId/cancel-approval')
  @HttpCode(200)
  async cancelApprovalAssetInspectionPlan(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE_MANAGER, ROLE_STAFF);
    const id = req.params['assetInspectionPlanId'];
    return transaction(async (db) => {
      const current = await findPlan(db, id);
      if (current.approvalStatus !== '승인') {
        throw new ApiError(409, 'INSPECTION_PLAN_STATUS_CONFLICT', '승인 상태의 계획만 승인취소할 수 있습니다.');
      }
      // TODO: 진행 중인 실사 확인(INSPECTION_IN_PROGRESS)은 실사 진행 테이블이 입력에 없어 구현하지 못함
      const rows = await db.query(
        'UPDATE asset_inspection_plan SET approval_status = \'승인취소\', updated_at = now() '
        + 'WHERE asset_inspection_plan_id = CAST(:id AS bigint) RETURNING approval_status AS "approvalStatus"',
        { id },
      );
      return rows[0];
    });
  }
}

