import { useState } from 'react';
import {
  call, useData, Badge, DateText, Filters, Band, DataTable, Pager, Drawer,
  Form, Field, TextInput, DateInput, Select, LookupSelect, RefName, ErrorText,
} from '../kit';
import type { PageProps, Row, Page } from '../kit';

const SIZE = 20;
const STATUS_OPTIONS: [string, string][] = [['신청', '신청'], ['승인', '승인'], ['승인취소', '승인취소']];

interface Editing {
  row: Row | null;
}

export default function FnSfr02505Page({ role, notify }: PageProps) {
  const [typeInput, setTypeInput] = useState('');
  const [statusInput, setStatusInput] = useState('');
  const [applied, setApplied] = useState({ inspectionType: '', approvalStatus: '' });
  const [page, setPage] = useState(0);
  const [editing, setEditing] = useState<Editing | null>(null);
  const [form, setForm] = useState<Row>({});
  const [actionError, setActionError] = useState('');

  const { data, error, reload } = useData<Page>(
    () => call<Page>('GET', '/asset-inspection-plans', role, undefined, { ...applied, page, size: SIZE }),
    [applied, page, role],
  );
  const rows = data ? data.items : [];
  const waiting = rows.filter((r) => r.approvalStatus === '신청');

  function search() {
    setPage(0);
    setApplied({ inspectionType: typeInput, approvalStatus: statusInput });
  }

  function reset() {
    setTypeInput('');
    setStatusInput('');
    setPage(0);
    setApplied({ inspectionType: '', approvalStatus: '' });
  }

  function openCreate() {
    setForm({ inspectionType: '', startDate: '', endDate: '', targetScope: '', managerId: '' });
    setEditing({ row: null });
  }

  function openEdit(row: Row) {
    setForm({
      inspectionType: row.inspectionType,
      startDate: row.startDate,
      endDate: row.endDate,
      targetScope: row.targetScope ?? '',
      managerId: row.managerId,
    });
    setEditing({ row });
  }

  function setValue(key: string, value: unknown) {
    setForm((prev) => ({ ...prev, [key]: value }));
  }

  async function submit() {
    if (!form.inspectionType || !form.startDate || !form.endDate || !form.managerId) {
      throw new Error('실사 유형, 실사 시작일, 실사 종료일, 실사 담당자를 입력하세요.');
    }
    if (String(form.startDate) > String(form.endDate)) {
      throw new Error('실사 시작일이 종료일보다 늦을 수 없습니다.');
    }
    const body: Row = {
      inspectionType: form.inspectionType,
      startDate: form.startDate,
      endDate: form.endDate,
      targetScope: form.targetScope,
      managerId: form.managerId,
    };
    if (editing && editing.row) {
      await call('PUT', '/asset-inspection-plans/' + editing.row.assetInspectionPlanId, role, body);
      notify('실사계획을 수정했습니다.');
    } else {
      await call('POST', '/asset-inspection-plans', role, body);
      notify('실사계획을 작성했습니다.');
    }
    setEditing(null);
    reload();
  }

  async function act(row: Row, action: 'approve' | 'cancel-approval', done: string) {
    setActionError('');
    try {
      await call('POST', '/asset-inspection-plans/' + row.assetInspectionPlanId + '/' + action, role, {});
      notify(done);
      reload();
    } catch (e) {
      setActionError(e instanceof Error ? e.message : '처리하지 못했습니다.');
    }
  }

  function actions(row: Row) {
    return (
      <span>
        {row.approvalStatus !== '승인' && (
          <button type='button' onClick={() => openEdit(row)}>수정</button>
        )}
        {row.approvalStatus === '신청' && (
          <button type='button' onClick={() => act(row, 'approve', '실사계획을 승인했습니다.')}>승인</button>
        )}
        {row.approvalStatus === '승인' && (
          <button type='button' onClick={() => act(row, 'cancel-approval', '실사계획 승인을 취소했습니다.')}>승인취소</button>
        )}
      </span>
    );
  }

  return (
    <div className='bento'>
      <section className='box span-4'>
        <h2>전체 계획</h2>
        <strong>{data ? data.total : 0}</strong>
      </section>
      <section className='box span-4'>
        <h2>승인 대기</h2>
        <strong>{waiting.length}</strong>
      </section>
      <section className='box span-4'>
        <h2>작성</h2>
        <button type='button' onClick={openCreate}>실사계획 작성</button>
      </section>
      <section className='box span-8'>
        <h2>실사계획</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label='실사 유형'>
            <TextInput value={typeInput} onChange={setTypeInput} />
          </Field>
          <Field label='승인 상태'>
            <Select value={statusInput} onChange={setStatusInput} options={STATUS_OPTIONS} placeholder='전체' />
          </Field>
        </Filters>
        <Band total={data ? data.total : 0} />
        {error && <ErrorText text={error} />}
        {actionError && <ErrorText text={actionError} />}
        <DataTable
          rows={rows}
          empty='실사계획이 없습니다.'
          columns={[
            { key: 'inspectionType', label: '실사 유형' },
            { key: 'startDate', label: '실사 시작일', render: (r) => <DateText value={r.startDate} /> },
            { key: 'endDate', label: '실사 종료일', render: (r) => <DateText value={r.endDate} /> },
            { key: 'targetScope', label: '실사 대상 범위' },
            { key: 'managerId', label: '실사 담당자', render: (r) => <RefName table='employee' role={role} value={r.managerId} /> },
            { key: 'approvalStatus', label: '승인 상태', render: (r) => <Badge value={r.approvalStatus} /> },
            { key: 'actions', label: '처리', render: actions },
          ]}
        />
        <Pager page={page} size={SIZE} total={data ? data.total : 0} onPage={setPage} />
      </section>
      <section className='box span-4'>
        <h2>처리 대기</h2>
        <DataTable
          rows={waiting}
          empty='승인 대기 중인 계획이 없습니다.'
          columns={[
            { key: 'inspectionType', label: '실사 유형' },
            { key: 'startDate', label: '실사 시작일', render: (r) => <DateText value={r.startDate} /> },
            { key: 'actions', label: '처리', render: actions },
          ]}
        />
      </section>
      {editing && (
        <Drawer title={editing.row ? '실사계획 수정' : '실사계획 작성'} onClose={() => setEditing(null)}>
          <Form onSubmit={submit} submit={editing.row ? '수정' : '작성'}>
            <Field label='실사 유형' required>
              <TextInput value={form.inspectionType} onChange={(v) => setValue('inspectionType', v)} />
            </Field>
            <Field label='실사 시작일' required>
              <DateInput value={form.startDate} onChange={(v) => setValue('startDate', v)} />
            </Field>
            <Field label='실사 종료일' required>
              <DateInput value={form.endDate} onChange={(v) => setValue('endDate', v)} />
            </Field>
            <Field label='실사 담당자' required>
              <LookupSelect table='employee' role={role} value={form.managerId} onChange={(v) => setValue('managerId', v)} />
            </Field>
            <Field label='실사 대상 범위' wide>
              <TextInput multiline value={form.targetScope} onChange={(v) => setValue('targetScope', v)} />
            </Field>
          </Form>
        </Drawer>
      )}
    </div>
  );
}
